content.content:
1	// Live run dashboard. All state derives from the SSE event stream — a fresh
2	// page load, a late join, and a mid-run reconnect are the same code path
3	// (server replays from Last-Event-ID).
4	
5	import { h } from '../dom.js';
6	import { api } from '../api.js';
7	import { openRunStream } from '../sse.js';
8	import { timeChart, targetColor, fmtNum, fmtMs } from '../charts.js';
9	
10	export function renderDashboard(app, runId) {
11	  const state = {
12	    hello: null,
13	    strategy: '',
14	    warmups: [],      // [{from, to}] unix-sec ranges for shading
15	    latRows: [],      // [ts, ...per-target {p50,p95,p99}] for percentile switching
16	    totals: {},       // per target id: {ok, cas, err, lastOps, p95}
17	    curLevel: null,   // latest level_start payload
18	    done: null,
19	  };
20	  let charts = {};
21	  let es = null;
22	  let ticker = null;
23	  let pct = 'p95';
24	
25	  // --- static skeleton ---
26	  const badge = h('span', { class: 'badge running' }, 'connecting…');
27	  const cancelBtn = h('button', { class: 'danger small', style: { display: 'none' }, onclick: async () => {
28	    cancelBtn.disabled = true;
29	    try { await api.cancelRun(runId); } catch { cancelBtn.disabled = false; }
30	  } }, 'Cancel run');
31	  const workloadNote = h('span', { class: 'progress-note' });
32	  const levelsStrip = h('div', { class: 'levels-strip' });
33	  const banners = h('div');
34	  const tiles = h('div', { class: 'tiles' });
35	  const chartsBox = h('div');
36	  const resultsBox = h('div');
37	
38	  app.append(
39	    h('div', { class: 'run-head' },
40	      h('h1', {}, `Run ${runId}`), badge, workloadNote, h('span', { class: 'spacer' }), cancelBtn),
41	    banners, levelsStrip, tiles, chartsBox, resultsBox);
42	
43	  const warned = sessionStorage.getItem(`fm-warn-${runId}`);
44	  if (warned) {
45	    for (const wtext of JSON.parse(warned)) banners.append(h('div', { class: 'banner warn' }, '⚠ ' + wtext));
46	  }
47	
48	  // --- charts are built once targets are known (hello) ---
49	  function buildCharts(targets) {
50	    const isClone = state.strategy === 'clone';
51	    const isSession = state.strategy === 'session';
52	    const bands = () => state.warmups;
53	
54	    const mk = (title, note, opts) => {
55	      const el = h('div');
56	      const head = h('div', { class: 'chart-head' }, h('h2', {}, title), note ? h('span', { class: 'u-note' }, note) : null);
57	      const card = h('div', { class: 'card chart-card' }, head, el);
58	      chartsBox.append(card);
59	      return { el, head, chart: timeChart(el, opts) };
60	    };
61	
62	    const tputSeries = targets.map((t) => ({ label: t.name, color: targetColor(t.id) }));
63	    if (isSession) {
64	      for (const t of targets) tputSeries.push({ label: `${t.name} clones`, color: targetColor(t.id), dash: [5, 5] });
65	    }
66	    charts.tput = mk(isClone ? 'Clone throughput' : 'Push throughput',
67	      isClone ? 'successful clones per second' : 'successful pushes per second' + (isSession ? ' · dashed = clones/s' : ''),
68	      { series: tputSeries, unit: fmtNum, bands }).chart;
69	
70	    const latHead = mk('Latency', `rolling 10s window · shaded = warm-up`, {
71	      series: targets.map((t) => ({ label: t.name, color: targetColor(t.id) })),
72	      unit: fmtMs, bands,
73	    });
74	    charts.lat = latHead.chart;
75	    const seg = h('div', { class: 'seg' }, ['p50', 'p95', 'p99'].map((p) =>
76	      h('button', { type: 'button', class: p === pct ? 'on' : '', onclick: (ev) => {
77	        pct = p;
78	        for (const b of seg.querySelectorAll('button')) b.classList.toggle('on', b.textContent === p);
79	        refeedLatency();
80	      } }, p)));
81	    latHead.head.append(seg);
82	
83	    const errSeries = [];
84	    for (const t of targets) errSeries.push({ label: `${t.name} err`, color: targetColor(t.id) });
85	    for (const t of targets) errSeries.push({ label: `${t.name} cas`, color: targetColor(t.id), dash: [5, 5] });
86	    charts.err = mk('Errors & contention', 'failures/s (solid) and CAS rejections/s (dashed)',
87	      { series: errSeries, unit: fmtNum, bands }).chart;
88	  }
89	
90	  function refeedLatency() {
91	    if (!charts.lat) return;
92	    charts.lat.setAll(state.latRows.map((r) => [r.ts, ...r.vals.map((v) => (v ? v[pct] : null))]));
93	  }
94	
95	  function buildTiles(targets) {
96	    tiles.innerHTML = '';
97	    for (const t of targets) {
98	      state.totals[t.id] = { ok: 0, cas: 0, err: 0, lastOps: 0, p95: 0 };
99	      t._tile = {
100	        ops: h('b', {}, '–'), p95: h('b', {}, '–'), errs: h('b', {}, '0'),
101	        label: h('div', { class: 'tlabel' }, t.remote),
102	        err: h('div', { class: 'terr', style: { display: 'none' } }),
