package server

import (
	"context"
	"fmt"
	"math"
	"math/rand"
	"net/url"
	"strconv"
	"sync"
	"time"

	"github.com/entireio/forgemark/internal/bench"
)

// demoRunner synthesizes push samples so the whole pipeline — level barriers,
// collector, SSE, charts, persistence — can be exercised and demoed with no
// forge and no network. It is selected by a demo:// remote:
//
//	demo://fast?p50=80ms&spread=3&err=0.01&cas=0.02&cap=200
//
//	p50     median latency (Go duration; default 80ms)
//	spread  p99/p50 shape multiplier of the log-normal tail (default 3)
//	err     probability an op fails (default 0.01)
//	cas     probability an op is a CAS rejection (default 0)
//	cap     ops/sec saturation ceiling; approaching it inflates latency the
//	        way a real forge queues (default 0 = unbounded)
//
// Each concurrency level runs c goroutines that sleep a sampled latency per
// op, so throughput scales with concurrency until cap bends the curve — the
// same shapes a real sweep produces.
type demoRunner struct {
	label   string
	w       bench.Workload
	sink    bench.Sink
	p50     time.Duration
	sigma   float64 // log-normal shape derived from spread
	errRate float64
	casRate float64
	cap     float64
}

func isDemoRemote(remote string) bool {
	u, err := url.Parse(remote)
	return err == nil && u.Scheme == "demo"
}

func newDemoRunner(remote string, w bench.Workload, sink bench.Sink) (*demoRunner, error) {
	u, err := url.Parse(remote)
	if err != nil || u.Scheme != "demo" {
		return nil, fmt.Errorf("invalid demo remote %q", remote)
	}
	q := u.Query()
	d := &demoRunner{label: remote, w: w, sink: sink, p50: 80 * time.Millisecond, errRate: 0.01}
	spread := 3.0
	if v := q.Get("p50"); v != "" {
		if d.p50, err = time.ParseDuration(v); err != nil || d.p50 <= 0 {
			return nil, fmt.Errorf("demo: invalid p50 %q", v)
		}
	}
	for name, dst := range map[string]*float64{"spread": &spread, "err": &d.errRate, "cas": &d.casRate, "cap": &d.cap} {
		if v := q.Get(name); v != "" {
			f, err := strconv.ParseFloat(v, 64)
			if err != nil || f < 0 {
				return nil, fmt.Errorf("demo: invalid %s %q", name, v)
			}
			*dst = f
		}
	}
	if spread < 1 {
		return nil, fmt.Errorf("demo: spread must be >= 1")
	}
	// For a log-normal around the median, p99 = median * exp(sigma * z99).
	d.sigma = math.Log(spread) / 2.326
	return d, nil
}

func (d *demoRunner) Label() string        { return d.label }
func (d *demoRunner) Nodes() int           { return 1 }
func (d *demoRunner) ObjectFormat() string { return "sha1" }

func (d *demoRunner) RunLevel(ctx context.Context, c int) (bench.LevelResult, error) {
	total := d.w.Warmup + d.w.Duration
	lctx, cancel := context.WithTimeout(ctx, total)
	defer cancel()

	// Saturation: offered load approaches cap → queueing inflates latency.
	inflate := 1.0
	if d.cap > 0 {
		offered := float64(c) / d.p50.Seconds()
		util := math.Min(offered/d.cap, 0.95)
		inflate = 1 / (1 - util)
	}

	start := time.Now()
	var mu sync.Mutex
	var all []bench.Sample
	var wg sync.WaitGroup
	for i := range c {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			// Deterministic per agent, like the engine's commit content rng.
			rng := rand.New(rand.NewSource(int64(id)*7919 + 42)) //nolint:gosec // synthetic demo data
			for lctx.Err() == nil {
				lat := time.Duration(float64(d.p50) * inflate * math.Exp(d.sigma*rng.NormFloat64()))
				t0 := time.Now()
				select {
				case <-time.After(lat):
				case <-lctx.Done():
					return // drop the truncated op, like the engine does
				}
				s := bench.Sample{Offset: t0.Sub(start), Dur: time.Since(t0)}
				switch roll := rng.Float64(); {
				case roll < d.errRate:
					s.Res = bench.OutcomeErr
					s.Msg = "demo: synthetic error"
				case roll < d.errRate+d.casRate:
					s.Res = bench.OutcomeCAS
				}
				if d.sink != nil {
					d.sink.OnSample(s)
				}
				mu.Lock()
				all = append(all, s)
				mu.Unlock()
			}
		}(i)
	}
	wg.Wait()
	return bench.SummarizeSamples(all, c, d.w.Strategy, 1, 1, d.w.Warmup, d.w.Duration, d.w.CommitDesc()), nil
}

package bench

import (
	"math"
	"sort"
	"time"
)

// Outcome classifies a single push attempt.
type Outcome int

const (
	OutcomeOK  Outcome = iota // push landed
	OutcomeCAS                // rejected by ref CAS / non-fast-forward (contention)
	OutcomeErr                // any other failure (transport, auth, server error)
)

// OpKind distinguishes which operation a sample measured. Zero value is OpPush
// so existing push-only call sites need no change.
type OpKind int

const (
	OpPush  OpKind = iota // a receive-pack push (the write path)
	OpClone               // a clone (the read path; clone/session strategy)
)

// sample is one recorded operation. offset is measured from the start of the
// concurrency level so warm-up samples can be dropped post-hoc.
type sample struct {
	offset time.Duration
	dur    time.Duration
	res    Outcome
	op     OpKind
	msg    string // raw error text, retained only when res == OutcomeErr
}

// Sample is the exported view of one recorded operation, delivered live to a
// Sink as the agent records it.
type Sample struct {
	Offset time.Duration // measured from level start; warm-up samples included
	Dur    time.Duration
	Res    Outcome
	Op     OpKind
	Msg    string // raw error text, only when Res == OutcomeErr
}

// Sink observes every sample live, warm-up included. OnSample is called
// concurrently from up to `concurrency` agent goroutines mid-measurement, so
// it must be cheap and non-blocking (a mutex-protected aggregator is fine; a
// slow sink would perturb the numbers being measured). A nil Sink disables
// observation — the CLI path.
type Sink interface {
	OnSample(s Sample)
}

// SummarizeSamples folds exported samples into a LevelResult exactly the way
// the engine folds its own (warm-up dropped, exact percentiles over OK
// samples). It exists for alternative sample sources — the server's demo
// target, tests — so their results are directly comparable to real ones.
func SummarizeSamples(samples []Sample, concurrency int, strategy string, repos, nodes int,
	warmup, window time.Duration, commitFiles string) LevelResult {
	in := make([]sample, len(samples))
	for i, s := range samples {
		in[i] = sample{offset: s.Offset, dur: s.Dur, res: s.Res, op: s.Op, msg: s.Msg}
	}
	return summarize(in, concurrency, strategy, repos, nodes, warmup, window, commitFiles)
}

// Percentile returns the nearest-rank percentile of an already-sorted slice.
func Percentile(sorted []float64, p float64) float64 { return percentile(sorted, p) }

// errMsg returns the message to retain on a sample. Only genuine errors carry
// text; OK and CAS outcomes stay message-free.
func errMsg(res Outcome, err error) string {
	if res != OutcomeErr || err == nil {
		return ""
	}
	return err.Error()
}

// LevelResult is the published summary for one concurrency level. JSON tags
// are the columns charts consume.
type LevelResult struct {
	Concurrency int     `json:"concurrency"`
	Strategy    string  `json:"strategy"`
	Repos       int     `json:"repos"`
	Nodes       int     `json:"nodes"`
	WindowSec   float64 `json:"window_sec"`
	Pushes      int     `json:"pushes"` // attempts in the measured window; clone strategy uses this as its primary op count
	OK          int     `json:"ok"`     // successful primary operations
	CASFailures int     `json:"cas_failures"`
	OtherErrors int     `json:"other_errors"`
	OpsPerSec   float64 `json:"ops_per_sec"` // OK / window
	P50ms       float64 `json:"p50_ms"`
	P95ms       float64 `json:"p95_ms"`
	P99ms       float64 `json:"p99_ms"`
	P999ms      float64 `json:"p999_ms"`
	Maxms       float64 `json:"max_ms"`
	CommitFiles string  `json:"commit_files"` // e.g. "1-10 x 2048B"

	// Clone/session-strategy read side (op==clone). Omitted in push/repo modes.
	Clones      int     `json:"clones,omitempty"`
	CloneOK     int     `json:"clone_ok,omitempty"`
	CloneErrors int     `json:"clone_errors,omitempty"`
	CloneP50ms  float64 `json:"clone_p50_ms,omitempty"`
	CloneP95ms  float64 `json:"clone_p95_ms,omitempty"`
	CloneP99ms  float64 `json:"clone_p99_ms,omitempty"`

	// Distinct error messages (normalized) with occurrence counts, for the err
	// bucket only. Omitted when there were no errors.
	ErrorMessages      []ErrGroup `json:"error_messages,omitempty"`
	CloneErrorMessages []ErrGroup `json:"clone_error_messages,omitempty"`
}

// ErrGroup is one distinct (normalized) error message and how often it occurred.
type ErrGroup struct {
	Message string `json:"message"`
	Count   int    `json:"count"`
}

// maxDistinctErrors caps how many distinct messages a level reports; the rest
// fold into an "(other errors)" bucket.
const maxDistinctErrors = 20

// errGroups folds raw error messages into a deterministic, bounded breakdown:
// normalize each distinct raw once (collapsing this run's volatile URLs/refs),
// tally by the resulting key, then keep the maxDistinctErrors most frequent
// (count desc, message asc) and fold the remainder into "(other errors)".
// Returns nil when there were no errors, so the JSON field is omitted.
func errGroups(raw map[string]int) []ErrGroup {
	if len(raw) == 0 {
		return nil
	}
	// Normalize once per distinct raw message, not once per occurrence — an
	// outage repeating one error tens of thousands of times normalizes it once.
	counts := make(map[string]int, len(raw))
	for msg, n := range raw {
		counts[normalizeErr(msg)] += n
	}
	out := make([]ErrGroup, 0, len(counts))
	for msg, n := range counts {
		out = append(out, ErrGroup{Message: msg, Count: n})
	}
	byFreq := func(i, j int) bool {
		if out[i].Count != out[j].Count {
			return out[i].Count > out[j].Count
		}
		return out[i].Message < out[j].Message
	}
	sort.Slice(out, byFreq)
	if len(out) > maxDistinctErrors {
		other := 0
		for _, g := range out[maxDistinctErrors:] {
			other += g.Count
		}
		out = append(out[:maxDistinctErrors], ErrGroup{Message: "(other errors)", Count: other})
		sort.Slice(out, byFreq) // the overflow bucket may outrank the kept singletons
	}
	return out
}

// summarize folds raw samples into a LevelResult, dropping anything inside the
// warm-up window and computing exact percentiles over the OK samples.
func summarize(samples []sample, concurrency int, strategy string, repos, nodes int,
	warmup, window time.Duration, commitFiles string) LevelResult {
	r := LevelResult{
		Concurrency: concurrency,
		Strategy:    strategy,
		Repos:       repos,
		Nodes:       nodes,
		WindowSec:   window.Seconds(),
		CommitFiles: commitFiles,
	}

	var okDurs, cloneDurs []float64
	pushErrs := map[string]int{}
	cloneErrs := map[string]int{}
	for _, s := range samples {
		if s.offset < warmup {
			continue // warm-up: excluded from every statistic
		}
		if s.op == OpClone {
			r.Clones++
			if s.res == OutcomeOK {
				r.CloneOK++
				cloneDurs = append(cloneDurs, float64(s.dur)/float64(time.Millisecond))
			} else {
				r.CloneErrors++
				cloneErrs[s.msg]++
			}
			continue
		}
		r.Pushes++
		switch s.res {
		case OutcomeOK:
			r.OK++
			okDurs = append(okDurs, float64(s.dur)/float64(time.Millisecond))
		case OutcomeCAS:
			r.CASFailures++
		case OutcomeErr:
			r.OtherErrors++
			pushErrs[s.msg]++
		}
	}
	r.ErrorMessages = errGroups(pushErrs)
	r.CloneErrorMessages = errGroups(cloneErrs)

	if len(okDurs) > 0 {
		sort.Float64s(okDurs)
		r.P50ms = percentile(okDurs, 50)
		r.P95ms = percentile(okDurs, 95)
		r.P99ms = percentile(okDurs, 99)
		r.P999ms = percentile(okDurs, 99.9)
		r.Maxms = okDurs[len(okDurs)-1]
	}
	if len(cloneDurs) > 0 {
		sort.Float64s(cloneDurs)
		r.CloneP50ms = percentile(cloneDurs, 50)
		r.CloneP95ms = percentile(cloneDurs, 95)
		r.CloneP99ms = percentile(cloneDurs, 99)
	}
	if strategy == "clone" {
		r.Pushes = r.Clones
		r.OK = r.CloneOK
		r.OtherErrors = r.CloneErrors
		r.CASFailures = 0
		r.ErrorMessages = r.CloneErrorMessages
		r.P50ms = r.CloneP50ms
		r.P95ms = r.CloneP95ms
		r.P99ms = r.CloneP99ms
		if len(cloneDurs) > 0 {
			r.P999ms = percentile(cloneDurs, 99.9)
			r.Maxms = cloneDurs[len(cloneDurs)-1]
		}
	}
	if window > 0 {
		r.OpsPerSec = float64(r.OK) / window.Seconds()
	}
	return r
}

// percentile returns the nearest-rank percentile of an already-sorted slice.
func percentile(sorted []float64, p float64) float64 {
	if len(sorted) == 0 {
		return 0
	}
	rank := int(math.Ceil(p/100*float64(len(sorted)))) - 1
	rank = max(rank, 0)
	rank = min(rank, len(sorted)-1)
	return sorted[rank]
}

package server

import (
	"sort"
	"sync"
	"time"

	"github.com/entireio/forgemark/internal/bench"
)

// windowSecs is the rolling-percentile window: latency percentiles in a bucket
// event are computed over the OK samples of the last windowSecs seconds, so a
// single quiet second doesn't blank the lines while spikes still show quickly.
const windowSecs = 10

// collector is the live aggregator for one target of one run. It implements
// bench.Sink: agents call OnSample concurrently mid-measurement, so it does
// only counter increments and one append under its mutex. Once per second the
// run's ticker calls snapshot, which swaps the current bucket out and computes
// rolling percentiles (an exact sort over the window — a few thousand floats,
// ~100µs, nothing at benchmark sample rates).
type collector struct {
	mu        sync.Mutex
	cur       bucket
	ring      [windowSecs][]float64 // push OK latencies, one slot per elapsed second
	cloneRing [windowSecs][]float64
	pos       int
}

// bucket accumulates one second of samples.
type bucket struct {
	ops, ok, cas, errs        int
	clones, cloneOK, cloneErr int
	lat                       []float64 // OK push latencies (ms)
	cloneLat                  []float64 // OK clone latencies (ms)
}

// BucketStats is one target's slice of a per-second bucket event. Push and
// clone ops are reported separately, mirroring LevelResult; the UI picks the
// primary series from the workload strategy.
type BucketStats struct {
	Ops int `json:"ops"`
	OK  int `json:"ok"`
	CAS int `json:"cas"`
	Err int `json:"err"`
	// Rolling percentiles over the last windowSecs seconds of OK pushes.
	P50 float64 `json:"p50_ms"`
	P95 float64 `json:"p95_ms"`
	P99 float64 `json:"p99_ms"`

	Clones   int     `json:"clones,omitempty"`
	CloneOK  int     `json:"clone_ok,omitempty"`
	CloneErr int     `json:"clone_err,omitempty"`
	CloneP50 float64 `json:"clone_p50_ms,omitempty"`
	CloneP95 float64 `json:"clone_p95_ms,omitempty"`
	CloneP99 float64 `json:"clone_p99_ms,omitempty"`
}

func (c *collector) OnSample(s bench.Sample) {
	ms := float64(s.Dur) / float64(time.Millisecond)
	c.mu.Lock()
	defer c.mu.Unlock()
	if s.Op == bench.OpClone {
		c.cur.clones++
		switch s.Res {
		case bench.OutcomeOK:
			c.cur.cloneOK++
			c.cur.cloneLat = append(c.cur.cloneLat, ms)
		default:
			c.cur.cloneErr++
		}
		return
	}
	c.cur.ops++
	switch s.Res {
	case bench.OutcomeOK:
		c.cur.ok++
		c.cur.lat = append(c.cur.lat, ms)
	case bench.OutcomeCAS:
		c.cur.cas++
	default:
		c.cur.errs++
	}
}

// snapshot closes out the current second: it returns its counters and the
// rolling percentiles over the updated window.
func (c *collector) snapshot() BucketStats {
	c.mu.Lock()
	b := c.cur
	c.cur = bucket{}
	c.ring[c.pos] = b.lat
	c.cloneRing[c.pos] = b.cloneLat
	c.pos = (c.pos + 1) % windowSecs
	var lat, cloneLat []float64
	for i := range c.ring {
		lat = append(lat, c.ring[i]...)
		cloneLat = append(cloneLat, c.cloneRing[i]...)
	}
	c.mu.Unlock()

	st := BucketStats{
		Ops: b.ops, OK: b.ok, CAS: b.cas, Err: b.errs,
		Clones: b.clones, CloneOK: b.cloneOK, CloneErr: b.cloneErr,
	}
	if len(lat) > 0 {
		sort.Float64s(lat)
		st.P50 = bench.Percentile(lat, 50)
		st.P95 = bench.Percentile(lat, 95)
		st.P99 = bench.Percentile(lat, 99)
	}
	if len(cloneLat) > 0 {
		sort.Float64s(cloneLat)
		st.CloneP50 = bench.Percentile(cloneLat, 50)
		st.CloneP95 = bench.Percentile(cloneLat, 95)
		st.CloneP99 = bench.Percentile(cloneLat, 99)
	}
	return st
}

// reset clears the bucket and the rolling window. Called at each level start
// so percentiles never bleed across concurrency levels.
func (c *collector) reset() {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.cur = bucket{}
	c.ring = [windowSecs][]float64{}
	c.cloneRing = [windowSecs][]float64{}
	c.pos = 0
}

