300	func (m *RunManager) clearActive(r *Run) {
301		m.mu.Lock()
302		defer m.mu.Unlock()
303		if m.active == r {
304			m.active = nil
305		}
306	}
307	
308	// coordinate is the run's driver goroutine: build runners, then walk the
309	// concurrency sweep with a barrier per level so every target starts each
310	// level at the same instant (the whole point of a comparison run).
311	func (r *Run) coordinate(m *RunManager) {
312		defer r.cancel()
313	
314		// Resolve every target concurrently — entiredb setup probes the cluster.
315		// A target that fails setup is dead but doesn't kill the comparison.
316		var wg sync.WaitGroup
317		for _, t := range r.targets {
318			wg.Add(1)
319			go func(t *targetState) {
320				defer wg.Done()
321				var (
322					lr  levelRunner
