1	// New-run form: one workload, 1..8 targets. Secrets go straight into the POST
2	// body and nowhere else (no localStorage, no URL).
3	
4	import { h } from '../dom.js';
5	import { api } from '../api.js';
6	import { targetColor } from '../charts.js';
7	
8	const strategies = [
9	  ['branch', 'branch — one repo, per-agent branches (headline write number)'],
10	  ['repo', 'repo — agents spread across N repos (horizontal scale)'],
11	  ['clone', 'clone — shallow-clone loop (read-side ceiling)'],
12	  ['session', 'session — clone + push checkpoints per session (agent lifecycle)'],
13	];
14	
15	let targetSeq = 0;
16	
17	function blankTarget() {
18	  return { key: ++targetSeq, name: '', remote: '', repos: '', user: '', secret: '', secret_source: '', insecure: false, object_format: 'auto', token_url: '', jurisdiction: '', client_id: '' };
19	}
20	
21	export function renderNewRun(app) {
22	  const targets = [blankTarget()];
23	  let errorBanner = null;
24	  let raceView = false;
25	
26	  const targetsBox = h('div');
27	  const startBtn = h('button', { class: 'primary', type: 'submit', disabled: true }, 'Start benchmark');
28	  const confirm = h('input', { type: 'checkbox', id: 'confirm', onchange: () => { startBtn.disabled = !confirm.checked; } });
29	
30	  function field(label, input, cls = '') {
31	    return h('div', { class: `field ${cls}` }, h('label', {}, label), input);
32	  }
33	  const inp = (attrs) => h('input', { type: 'text', ...attrs });
34	
35	  // --- workload inputs (queried on submit) ---
36	  const w = {
37	    strategy: h('select', { onchange: () => syncStrategy() }, strategies.map(([v, t]) => h('option', { value: v }, t))),
38	    concurrency: inp({ value: '1,8,32', placeholder: 'e.g. 1,8,32,128' }),
39	    duration_sec: inp({ value: '60' }),
40	    warmup_sec: inp({ value: '10' }),
41	    files_min: inp({ value: '1' }),
42	    files_max: inp({ value: '10' }),
43	    file_size: inp({ value: '2048' }),
44	    branch_prefix: inp({ value: '', placeholder: 'e.g. bench/' }),
45	    session_commits: inp({ value: '5' }),
46	    clone_depth: inp({ value: '1' }),
47	    base_ref: inp({ value: '', placeholder: 'default branch' }),
48	  };
49	
50	  const commitFields = h('div', { class: 'grid c3' },
51	    field('Files per commit (min)', w.files_min),
52	    field('Files per commit (max)', w.files_max),
53	    field('Bytes per file', w.file_size));
54	  const cloneFields = h('div', { class: 'grid c3' },
55	    field('Session commits', w.session_commits),
56	    field('Clone depth (0 = full)', w.clone_depth),
57	    field('Base ref', w.base_ref));
58	
59	  function syncStrategy() {
60	    const s = w.strategy.value;
61	    commitFields.style.display = s === 'clone' ? 'none' : '';
62	    cloneFields.style.display = (s === 'clone' || s === 'session') ? '' : 'none';
63	    w.session_commits.parentElement.style.display = s === 'session' ? '' : 'none';
64	  }
65	
66	  function renderTargets() {
67	    targetsBox.innerHTML = '';
68	    targets.forEach((t, i) => targetsBox.append(targetCard(t, i)));
69	  }
70	
71	  function targetCard(t, i) {
72	    const bind = (key, input) => {
73	      input.value = t[key];
74	      input.addEventListener('input', () => { t[key] = input.value; });
75	      return input;
76	    };
77	    const insecure = h('input', { type: 'checkbox', style: { width: 'auto' }, onchange: (e) => { t.insecure = e.target.checked; } });
78	    insecure.checked = t.insecure;
79	
80	    // Credential: paste a token, or name a CLI the server pulls it from at
81	    // start (the browser then never holds the secret).
82	    const secretInput = bind('secret', inp({ type: 'password', autocomplete: 'off', placeholder: 'kept in memory only' }));
83	    const srcSel = h('select', { onchange: () => {
84	      t.secret_source = srcSel.value;
85	      secretInput.style.display = srcSel.value ? 'none' : '';
86	      if (srcSel.value) { t.secret = ''; secretInput.value = ''; }
87	    } },
88	      h('option', { value: '' }, 'paste token'),
89	      h('option', { value: 'gh' }, 'gh CLI login'),
90	      h('option', { value: 'entire' }, 'entire CLI login'));
91	    srcSel.value = t.secret_source;
92	    secretInput.style.display = t.secret_source ? 'none' : '';
93	
94	    return h('div', { class: 'target-card', style: { '--tcolor': targetColor(i) } },
95	      h('div', { class: 'thead' },
96	        h('span', { class: 'tname' }, h('span', { class: 'dot', style: { '--tcolor': targetColor(i), marginRight: '8px' } }), `Target ${i + 1}`),
97	        targets.length > 1 ? h('button', { class: 'small danger', type: 'button', onclick: () => { targets.splice(i, 1); renderTargets(); } }, 'Remove') : null),
98	      h('div', { class: 'grid c3' },
99	        field('Name (chart label)', bind('name', inp({ placeholder: 'e.g. gitlab-prod' }))),
100	        field('Remote base URL', bind('remote', inp({ placeholder: 'https://gitlab.example — or demo://fast?p50=80ms' })), 'wide'),
101	      ),
102	      h('div', { class: 'grid c3', style: { marginTop: '12px' } },
103	        field('Repos (comma-separated)', bind('repos', inp({ placeholder: 'group/bench.git' }))),
104	        field('Username (token forges ignore it)', bind('user', inp({ placeholder: 'x-access-token' }))),
105	        field('Credential', h('div', { class: 'cred-row' }, srcSel, secretInput)),
106	      ),
107	      h('div', { class: 'grid c3', style: { marginTop: '12px' } },
108	        field('Object format', bind('object_format', h('select', {},
109	          h('option', { value: 'auto' }, 'auto'), h('option', { value: 'sha1' }, 'sha1'), h('option', { value: 'sha256' }, 'sha256')))),
110	        h('div', { class: 'field' }, h('label', {}, 'TLS'), h('label', { style: { color: 'var(--ink-2)', fontSize: '13px' } }, insecure, ' skip verification (dev hosts)')),
111	      ),
112	      h('details', { class: 'entire' },
113	        h('summary', {}, 'entiredb (jurisdiction token exchange)'),
114	        h('div', { class: 'grid c3' },
115	          field('Token URL', bind('token_url', inp({ placeholder: 'https://…/oauth/token' }))),
116	          field('Jurisdiction', bind('jurisdiction', inp({ placeholder: 'https://us.example.com' }))),
117	          field('Client ID', bind('client_id', inp({ placeholder: 'entire-cli' }))))));
118	  }
119	
120	  // --- presets & CLI target discovery ---
121	  const raceViewChk = h('input', { type: 'checkbox', id: 'raceview', style: { width: 'auto' }, onchange: () => { raceView = raceViewChk.checked; } });
122	
123	  function applyRacePreset() {
124	    w.strategy.value = 'branch';
125	    w.concurrency.value = '16';
126	    w.duration_sec.value = '60';
127	    w.warmup_sec.value = '0';
128	    w.files_min.value = '1'; w.files_max.value = '3'; w.file_size.value = '1024';
129	    w.branch_prefix.value = 'bench/';
130	    raceView = true; raceViewChk.checked = true;
131	    syncStrategy();
132	  }
133	
134	  const cliNotes = h('div');
135	  const cliBtn = h('button', { type: 'button', onclick: addFromCLI }, 'Add from CLI logins');
136	  async function addFromCLI() {
137	    cliBtn.disabled = true;
138	    cliBtn.textContent = 'detecting…';
139	    cliNotes.innerHTML = '';
140	    try {
141	      const sug = await api.localSuggest();
142	      for (const key of ['github', 'entire']) {
143	        const e = sug[key] || {};
144	        if (e.target) {
145	          const s = e.target;
146	          if (targets.some((t) => t.remote === s.remote && t.repos === (s.repos || []).join(','))) continue;
147	          targets.push({
148	            ...blankTarget(),
149	            name: s.name || '', remote: s.remote || '', repos: (s.repos || []).join(','),
150	            user: s.user || '', secret_source: s.secret_source || '',
151	            token_url: s.token_url || '', jurisdiction: s.jurisdiction || '', client_id: s.client_id || '',
152	          });
153	          if (e.note) cliNotes.append(h('div', { class: 'banner' }, `${s.name}: ${e.note}`));
154	        } else if (e.error) {
155	          cliNotes.append(h('div', { class: 'banner warn' }, `${key}: ${e.error}`));
156	        }
157	      }
158	      if (targets.length > 1 && !targets[0].remote) targets.shift();
159	      renderTargets();
160	    } catch (err) {
161	      cliNotes.append(h('div', { class: 'banner error' }, String(err.message || err)));
162	    } finally {
163	      cliBtn.disabled = false;
164	      cliBtn.textContent = 'Add from CLI logins';
165	    }
166	  }
167	
168	  async function submit(ev) {
169	    ev.preventDefault();
170	    if (errorBanner) { errorBanner.remove(); errorBanner = null; }
171	    const num = (el) => parseFloat(el.value || '0');
172	
173	    // Reject malformed concurrency instead of silently dropping tokens: an
174	    // empty list would make the server substitute its default [1,8,32,128]
175	    // sweep — a 128-agent surprise the user never asked for.
176	    const concTokens = w.concurrency.value.split(',').map((s) => s.trim()).filter(Boolean);
177	    const concurrency = concTokens.map((s) => parseInt(s, 10));
178	    if (!concurrency.length || concurrency.some((n, i) => !Number.isInteger(n) || n < 1 || String(n) !== concTokens[i])) {
179	      errorBanner = h('div', { class: 'banner error' },
180	        `Concurrency must be comma-separated positive integers (e.g. 1,8,32) — got "${w.concurrency.value}"`);
181	      form.prepend(errorBanner);
182	      window.scrollTo(0, 0);
183	      return;
184	    }
185	
186	    const spec = {
187	      confirm_authorized: confirm.checked,
188	      workload: {
189	        strategy: w.strategy.value,
190	        concurrency,
191	        duration_sec: num(w.duration_sec),
192	        warmup_sec: num(w.warmup_sec),
193	        files_min: num(w.files_min), files_max: num(w.files_max), file_size: num(w.file_size),
194	        branch_prefix: w.branch_prefix.value,
195	        session_commits: num(w.session_commits), clone_depth: num(w.clone_depth), base_ref: w.base_ref.value,
196	      },
197	      targets: targets.map((t) => ({
198	        name: t.name, remote: t.remote,
199	        repos: t.repos.split(',').map((s) => s.trim()).filter(Boolean),
200	        user: t.user, secret: t.secret, secret_source: t.secret_source,
201	        insecure: t.insecure, object_format: t.object_format,
202	        token_url: t.token_url, jurisdiction: t.jurisdiction, client_id: t.client_id,
203	      })),
204	    };
205	    startBtn.disabled = true;
206	    try {
207	      const res = await api.startRun(spec);
208	      if (res.warnings && res.warnings.length) {
209	        sessionStorage.setItem(`fm-warn-${res.id}`, JSON.stringify(res.warnings));
210	      }
211	      location.hash = raceView ? `#race/${res.id}` : `#run/${res.id}`;
212	    } catch (err) {
213	      startBtn.disabled = !confirm.checked;
214	      errorBanner = h('div', { class: 'banner error' }, String(err.message || err));
215	      form.prepend(errorBanner);
216	      window.scrollTo(0, 0);
217	    }
218	  }
219	
220	  const form = h('form', { onsubmit: submit },
221	    h('h1', {}, 'New benchmark run'),
222	    h('p', { class: 'sub' }, 'Drive real git pushes and clones against one or more forges and watch them side by side. Try it instantly with a ', h('code', {}, 'demo://'), ' target — no forge needed.'),
223	    h('div', { class: 'card' },
224	      h('div', { class: 'chart-head' },
225	        h('h2', {}, 'Workload'),
226	        h('span', { class: 'spacer' }),
227	        h('button', { type: 'button', class: 'small', onclick: applyRacePreset }, '⚡ Push race preset'),
228	        h('label', { style: { color: 'var(--ink-2)', fontSize: '13px', display: 'flex', alignItems: 'center', gap: '6px' } },
229	          raceViewChk, 'open race view')),
230	      h('div', { class: 'grid c4' },
231	        field('Strategy', w.strategy, 'wide'),
232	        field('Concurrency sweep', w.concurrency),
233	        field('Duration per level (s)', w.duration_sec),
234	        field('Warm-up (s)', w.warmup_sec),
235	        field('Branch prefix', w.branch_prefix)),
236	      h('div', { style: { marginTop: '12px' } }, commitFields),
237	      h('div', { style: { marginTop: '12px' } }, cloneFields)),
238	    h('div', { class: 'card' },
239	      h('h2', {}, 'Targets'),
240	      targetsBox,
241	      h('div', { style: { display: 'flex', gap: '10px' } },
242	        h('button', { type: 'button', onclick: () => { if (targets.length < 8) { targets.push(blankTarget()); renderTargets(); } } }, '+ Add target'),
243	        cliBtn,
244	        h('button', { type: 'button', class: 'small', onclick: () => {
245	          targets.push({ ...blankTarget(), name: 'demo-fast', remote: 'demo://fast?p50=60ms&spread=3&err=0.01&cap=400' });
246	          targets.push({ ...blankTarget(), name: 'demo-slow', remote: 'demo://slow?p50=180ms&spread=4&err=0.03&cas=0.02&cap=120' });
247	          if (targets.length > 2 && !targets[0].remote) targets.shift();
248	          renderTargets();
249	        } }, 'Add demo pair')),
250	      cliNotes),
251	    h('div', { class: 'confirm-row' },
252	      confirm,
253	      h('label', { for: 'confirm' }, 'I own this infrastructure or am explicitly authorized to load-test it. A benchmark run is sustained, abusive-looking traffic to any host that has not agreed to it.')),
254	    startBtn);
255	
256	  app.append(form);
257	  renderTargets();
258	  syncStrategy();
259	}
260

