          h('div', { style: { marginTop: '12px' } }, cloneFields))),
      confirmRow,
      h('div', { class: 'start-row' },
        startBtn,
        h('label', { class: 'race-toggle' }, raceChk, 'Open the live race view')));

    raceChk.checked = raceView;
    renderTargets();
    syncStrategy();
    updateWorkloadSummary();
  }

