          targets.push(blankTarget({
            name: s.name || '', remote: s.remote || '', repos: (s.repos || []).join(','),
            user: s.user || '', secret_source: s.secret_source || '',
            token_url: s.token_url || '', jurisdiction: s.jurisdiction || '', client_id: s.client_id || '',
          }));
