1	package bench
2	
3	import (
4		"context"
5		"crypto/tls"
6		"errors"
7		"fmt"
8		"net/http"
9		"slices"
10		"strings"
11		"sync"
12		"time"
13	
14		formatcfg "github.com/go-git/go-git/v6/plumbing/format/config"
15	)
16	
17	// Runner drives one target through concurrency levels of one workload. The
18	// caller owns the sweep loop: it calls RunLevel once per level, so level
19	// lifecycle (start/end, the returned LevelResult) is the caller's to observe —
20	// the engine only reports per-operation samples, via the optional Sink.
21	type Runner struct {
22		target Target
23		w      Workload
24		creds  credentialProvider
25		ep     *endpoint
26		httpc  *http.Client
27		sink   Sink
28	}
29	
30	// NewRunner resolves a target (credentials + endpoint; for entiredb this
31	// probes the cluster) and validates the workload against it. sink may be nil.
32	func NewRunner(ctx context.Context, t Target, w Workload, sink Sink) (*Runner, error) {
33		if err := w.Validate(); err != nil {
34			return nil, err
35		}
36		if len(t.Repos) == 0 {
37			return nil, errors.New("no repos: pass -repos or -repo-pattern + -repo-count")
38		}
39		if w.Strategy == "repo" && len(t.Repos) < 2 {
40			return nil, errors.New("strategy=repo needs >= 2 repos")
41		}
42		if t.Secret == "" {
43			return nil, errors.New("no credential secret provided")
44		}
45		httpc := newHTTPClient(t.Insecure, slices.Max(w.Concurrency)+8)
46	
47		var (
48			creds credentialProvider
49			ep    *endpoint
50			err   error
51		)
52		if t.TokenURL != "" || t.Jurisdiction != "" {
53			creds, ep, err = setupEntiredb(ctx, t, httpc)
54		} else {
55			creds, ep, err = setupGeneric(t)
56		}
57		if err != nil {
58			return nil, err
59		}
60		return &Runner{target: t, w: w, creds: creds, ep: ep, httpc: httpc, sink: sink}, nil
61	}
62	
63	// Label is the resolved endpoint label (the remote base URL), for banners and
64	// results.
65	func (r *Runner) Label() string { return r.ep.label }
66	
67	// Nodes is how many push destinations the endpoint fans out across (1 for any
68	// plain forge; the discovered replica count for entiredb).
69	func (r *Runner) Nodes() int { return len(r.ep.nodes) }
70	
71	// ObjectFormat is the resolved wire object format ("sha1" or "sha256").
72	func (r *Runner) ObjectFormat() string { return string(r.ep.objFmt) }
73	
74	// RunLevel runs a single concurrency level: spin up c agents for
75	// warmup+duration, then fold their samples into one result. It blocks for the
76	// full level window (or until ctx is cancelled).
77	func (r *Runner) RunLevel(ctx context.Context, c int) (LevelResult, error) {
78		var clone *cloneConfig
79		var sess *sessionConfig
80		switch r.w.Strategy {
81		case "clone":
82			clone = &cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef}
83		case "session":
84			sess = &sessionConfig{
85				cloneConfig: cloneConfig{cloneDepth: r.w.CloneDepth, baseRef: r.w.BaseRef},
86				commits:     r.w.SessionCommits,
87			}
88		}
89		agents := make([]*agent, c)
90		for i := range c {
91			repoPath := r.target.Repos[0]
92			if r.w.Strategy == "repo" {
93				repoPath = r.target.Repos[i%len(r.target.Repos)]
94			}
95			node := r.ep.nodes[i%len(r.ep.nodes)]
96			ref := DestRef(r.w.BranchPrefix, r.w.RunID, c, i)
97			a, err := newAgent(i, repoPath, node, ref, r.ep.objFmt, &r.w.Commit, r.creds, r.httpc, clone, sess, r.sink)
98			if err != nil {
99				return LevelResult{}, fmt.Errorf("new agent %d: %w", i, err)
100			}
101			agents[i] = a
102		}
103	
104		total := r.w.Warmup + r.w.Duration
105		lvlCtx, cancel := context.WithTimeout(ctx, total)
106		defer cancel()
107	
108		start := time.Now()
109		var wg sync.WaitGroup
110		for _, a := range agents {
111			wg.Add(1)
112			go func(a *agent) {
113				defer wg.Done()
114				a.run(lvlCtx, start)
115			}(a)
116		}
117		wg.Wait()
118	
119		var all []Sample
120		for _, a := range agents {
121			all = append(all, a.samples...)
122		}
123		reposUsed := 1
124		if r.w.Strategy == "repo" {
125			reposUsed = min(c, len(r.target.Repos))
126		}
127		return summarize(all, c, r.w.Strategy, reposUsed, len(r.ep.nodes), r.w.Warmup, r.w.Duration, r.w.CommitDesc()), nil
128	}
