{
  "id": "trail-review",
  "display_name": "ForgeMark Contract Review",
  "enabled": true,
  "scope": "trail",
  "runtime": {
    "kind": "prompt_runner",
    "agent": "codex",
    "model": "gpt-5.6-sol",
    "timeout_ms": 600000,
    "extra_args": [
      "-c",
      "model_reasoning_effort=\"medium\""
    ],
