1	// Package results reads and writes forgemark result documents. Two formats
2	// exist on disk in the same results/ directory:
3	//
4	//	format 1 (legacy, no "format" field): what the CLI has always written —
5	//	    one target, top-level "target"/"levels" fields. The CLI keeps writing
6	//	    this shape for strict compatibility with existing tooling.
7	//	format 2: what the server writes — multi-target, per-target level results
8	//	    plus the per-second live series so a finished run re-renders fully.
9	//
10	// Load normalizes format 1 into a one-target format 2 view, so consumers (the
11	// history UI) only ever see one shape.
12	package results
13	
14	import (
15		"encoding/json"
16		"errors"
17		"fmt"
18		"os"
19		"path/filepath"
20		"regexp"
21		"sort"
22		"time"
23	
24		"github.com/entireio/forgemark/internal/bench"
25	)
26	
27	// Doc is a stored run. Exactly one of the two shapes is populated on disk;
28	// Load always returns the Targets shape.
29	type Doc struct {
30		Format   int    `json:"format,omitempty"` // 2; absent/0 = legacy CLI doc
31		RunID    string `json:"run_id"`
32		Strategy string `json:"strategy"`
33		Duration string `json:"duration"`
34		Warmup   string `json:"warmup"`
35		Commit   string `json:"commit"`
36	
37		// format 2
38		State   string         `json:"state,omitempty"` // done | cancelled | failed
39		Targets []TargetResult `json:"targets,omitempty"`
40	
41		// format 1 (legacy CLI)
42		Target    string              `json:"target,omitempty"`
43		RepoCount int                 `json:"repo_count,omitempty"`
44		Levels    []bench.LevelResult `json:"levels,omitempty"`
45	}
46	
47	// TargetResult is one target's outcome within a run.
48	type TargetResult struct {
49		Name   string              `json:"name"`
50		Label  string              `json:"label,omitempty"`
51		Error  string              `json:"error,omitempty"` // fatal target error, if it died
52		Levels []bench.LevelResult `json:"levels"`
53		Series []SeriesPoint       `json:"series,omitempty"` // 1s live buckets, for re-rendering
54	}
55	
56	// SeriesPoint is one second of one target's live stats. Push and clone ops
57	// are kept separately, mirroring the live bucket event, so clone/session runs
58	// replay from history with the same fidelity they streamed with.
59	type SeriesPoint struct {
60		T     int64   `json:"t"`
61		Level int     `json:"level"`
62		OK    int     `json:"ok"`
63		CAS   int     `json:"cas"`
64		Err   int     `json:"err"`
65		P50   float64 `json:"p50_ms"`
66		P95   float64 `json:"p95_ms"`
67		P99   float64 `json:"p99_ms"`
68	
69		CloneOK  int     `json:"clone_ok,omitempty"`
70		CloneErr int     `json:"clone_err,omitempty"`
71		CloneP50 float64 `json:"clone_p50_ms,omitempty"`
72		CloneP95 float64 `json:"clone_p95_ms,omitempty"`
73		CloneP99 float64 `json:"clone_p99_ms,omitempty"`
74	}
75	
76	// Summary is one history listing entry.
77	type Summary struct {
78		File     string    `json:"file"`
79		RunID    string    `json:"run_id"`
80		Strategy string    `json:"strategy"`
81		State    string    `json:"state,omitempty"`
82		Targets  []string  `json:"targets"`
83		Levels   int       `json:"levels"`
84		ModTime  time.Time `json:"mtime"`
85	}
86	
87	// ErrNotFound reports a missing result file.
88	var ErrNotFound = errors.New("result file not found")
89	
90	// validFile is the only filename shape this package will touch. It doubles as
91	// the path-traversal guard for filenames arriving from HTTP.
92	var validFile = regexp.MustCompile(`^forgemark-[A-Za-z0-9._-]+\.json$`)
93	
94	// Write stores a doc as <dir>/<file>, creating dir if needed. The filename
95	// must match the discoverable forgemark-*.json shape.
96	func Write(dir, file string, doc Doc) error {
97		if !validFile.MatchString(file) {
98			return fmt.Errorf("invalid result filename %q", file)
99		}
100		return Save(filepath.Join(dir, file), doc)
101	}
102	
103	// Save stores a doc at an arbitrary path (the CLI's -out escape hatch),
104	// creating the parent directory if needed. Files outside the forgemark-*.json
105	// shape won't be discovered by List — that's the caller's tradeoff.
106	func Save(path string, doc Doc) error {
107		if dir := filepath.Dir(path); dir != "." {
108			if err := os.MkdirAll(dir, 0o750); err != nil {
109				return fmt.Errorf("mkdir %s: %w", dir, err)
110			}
111		}
112		b, err := json.MarshalIndent(doc, "", "  ")
113		if err != nil {
114			return fmt.Errorf("marshal results: %w", err)
115		}
116		if err := os.WriteFile(path, b, 0o600); err != nil {
117			return fmt.Errorf("write results: %w", err)
118		}
119		return nil
120	}
121	
122	// List summarizes every parseable result doc in dir, newest first. Unparseable
123	// files are skipped, not fatal — the directory is shared and hand-editable.
124	func List(dir string) ([]Summary, error) {
125		entries, err := os.ReadDir(dir)
126		if errors.Is(err, os.ErrNotExist) {
127			return []Summary{}, nil
128		}
129		if err != nil {
130			return nil, err
131		}
132		out := []Summary{}
133		for _, e := range entries {
134			if e.IsDir() || !validFile.MatchString(e.Name()) {
135				continue
136			}
137			doc, err := Load(dir, e.Name())
138			if err != nil {
139				continue
140			}
141			info, err := e.Info()
142			if err != nil {
143				continue
144			}
145			s := Summary{
146				File: e.Name(), RunID: doc.RunID, Strategy: doc.Strategy,
147				State: doc.State, ModTime: info.ModTime(),
148			}
149			for _, t := range doc.Targets {
150				s.Targets = append(s.Targets, t.Name)
151				s.Levels = max(s.Levels, len(t.Levels))
152			}
153			out = append(out, s)
154		}
155		// Newest first: the history view leads with the latest run.
156		sort.Slice(out, func(i, j int) bool { return out[i].ModTime.After(out[j].ModTime) })
157		return out, nil
158	}
159	
160	// Load reads one doc and normalizes legacy CLI docs into the Targets shape.
161	func Load(dir, file string) (Doc, error) {
162		if !validFile.MatchString(file) {
163			return Doc{}, fmt.Errorf("invalid result filename %q", file)
164		}
165		b, err := os.ReadFile(filepath.Join(dir, file))
166		if errors.Is(err, os.ErrNotExist) {
167			return Doc{}, ErrNotFound
168		}
169		if err != nil {
170			return Doc{}, err
171		}
172		var doc Doc
173		if err := json.Unmarshal(b, &doc); err != nil {
174			return Doc{}, fmt.Errorf("parse %s: %w", file, err)
175		}
176		if doc.Format == 0 && len(doc.Targets) == 0 {
177			// Legacy CLI doc: present it as one pseudo-target named by its label.
178			doc.Targets = []TargetResult{{Name: doc.Target, Label: doc.Target, Levels: doc.Levels}}
179			doc.State = "done"
180		}
181		doc.Target, doc.Levels = "", nil // consumers only see the normalized shape
182		return doc, nil
183	}
